import{_ as o,l as i,o as e,c as s,v as t,p as n,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Tail at Scale","description":"","frontmatter":{"title":"Tail at Scale","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tail-at-scale.md","filePath":"cs/tail-at-scale.md","lastUpdated":1789023840000}'),A={name:"cs/tail-at-scale.md"};function h(E,a,_,u,B,m){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="tail-at-scale" tabindex="-1">Tail at Scale <a class="header-anchor" href="#tail-at-scale" aria-label="Permalink to &quot;Tail at Scale&quot;">​</a></h1><div class="epigraph"><p>规模把罕见变常见：千分之一的慢，在扇出足够大时变成每次用户请求的常态。要在每一层减尾，而不是只加速平均数。</p><footer>—— 据 Dean and Barroso, The Tail at Scale, CACM 2013 整理</footer></div><p><a href="/cs/borg-kubernetes">上一课</a>把集群调度钉成 Borg / Kubernetes。<a href="/cs/tail-latency-hedging">对冲请求</a>已用第二份换 P99。缺口是<strong>把同一篇文章读成系统设计清单</strong>：微分区、请求截止、大类隔离、队列管理，以及为何共享集群让尾更肥。本课不重写对冲算法细节。后课分布式 ID 是另一条「规模下的生成器」问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户请求 = 许多微服务 × 许多分片。尾延迟分布有长尾，最大值的期望随扇出变坏。来源：后台作业、垃圾回收、磁盘寻道、包重传、邻居干扰、慢盘。平均数优化（更好的中位数机器）不自动砍尾。</p><p>Dean–Barroso 清单：对冲/备用请求、把大作业切小（微分区）、按类隔离队列、快速失败、同步打破（不齐步）、复制选择性。缺口：只在网关对冲，底层队列仍堆着不取消的工作。</p><p><span class="marginnote">与通信课的对冲课分工：那课钉 RPC 第二份；本课钉规模为何让尾变成一等指标，以及多层对策。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SLO 用尾不用均。取消要贯穿。批处理与交互分池，接 Borg 的优先级。避免全局锁与单热分片（热键课）。测量用追踪看哪一跳贡献 P99，接三支柱。</p>',9)),(e(),n(p,null,{default:r(()=>[d(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAN%5B%22%E5%A4%A7%E6%89%87%E5%87%BA%22%5D%20--%3E%20MAX%5B%22%E5%B0%BE%E8%A2%AB%E6%94%BE%E5%A4%A7%22%5D%0A%20%20MAX%20--%3E%20HEDGE%5B%22%E5%AF%B9%E5%86%B2%20%2F%20%E6%88%AA%E6%AD%A2%22%5D%0A%20%20MAX%20--%3E%20ISO%5B%22%E9%9A%94%E7%A6%BB%E9%98%9F%E5%88%97%22%5D%0A%20%20MAX%20--%3E%20PART%5B%22%E5%BE%AE%E5%88%86%E5%8C%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要用「再买更快的 CPU」当唯一手段：共享与排队会把快机器变慢尾。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同步：所有分片等最慢者（barrier）把尾变成和。能流式返回则流式。重试无抖动在规模下变成同步惊群。熔断保护平均数，也可能把尾变成立即错误——错误预算要算进去。</p><p>本课不把 CACM 文当成金融交易所低延迟设计。也不写光刻。</p><p>多租户：Borg 的 best-effort 任务会偷周期，guarantee 档减尾但降利用率。这是 PACELC 在延迟–成本上的投影，不是 CAP 分区。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给具体 P99 毫秒数当规范。后课默认：规模服务的规格写尾延迟与扇出；对策多层。分布式 ID 下一课避免中心计数器成为尾与热点。地理复制把延迟下限变成光速。</p><p>砍尾是架构税。只优化均值的报表会在扇出后说谎。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扇出把稀有慢变成用户常态。</li><li>对冲、隔离、微分区、可取消、打破屏障。</li><li>共享集群利用率与尾延迟交换。</li><li>出处：Dean and Barroso, CACM 2013。</li></ul>',10))])}const P=o(A,[["render",h]]);export{T as __pageData,P as default};
